import test from 'node:test'; import assert from 'node:assert/strict'; import {find} from './search.mjs'; test('search preserves records and order',()=>{const rows=[{id:1,title:'Alpha'},{id:2,title:'Beta'}]; const before=JSON.stringify(rows); assert.deepEqual(find(rows,'Al').map(x=>x.id),[1]); assert.equal(JSON.stringify(rows),before);});

test('search matches the beginning, middle, and end of titles', () => {
  const rows = [
    {id: 1, title: 'Alpha record'},
    {id: 2, title: 'The Alpha record'},
    {id: 3, title: 'Archive Alpha'},
    {id: 4, title: 'Beta'},
  ];
  assert.deepEqual(find(rows, 'Alpha').map(row => row.id), [1, 2, 3]);
  assert.deepEqual(find(rows, 'Missing'), []);
});

test('search ignores title and query letter case', () => {
  const rows = [
    {id: 1, title: 'aLpHa'},
    {id: 2, title: 'ALPHA'},
    {id: 3, title: 'alpha'},
    {id: 4, title: 'Beta'},
  ];
  assert.deepEqual(find(rows, 'AlPhA').map(row => row.id), [1, 2, 3]);
});

test('search trims surrounding query whitespace and preserves internal spaces', () => {
  const rows = [
    {id: 1, title: 'The Alpha record'},
    {id: 2, title: 'The Alpharecord'},
  ];
  assert.deepEqual(find(rows, '\t ALPHA record \n').map(row => row.id), [1]);
});

test('normalized search preserves record identity, input data, and result order', () => {
  const rows = Object.freeze([
    Object.freeze({id: 3, title: 'Archive ALPHA'}),
    Object.freeze({id: 1, title: 'Beta'}),
    Object.freeze({id: 2, title: 'The alpha record'}),
  ]);
  const before = JSON.stringify(rows);
  const result = find(rows, ' AlPhA ');
  assert.deepEqual(result.map(row => row.id), [3, 2]);
  assert.equal(result[0], rows[0]);
  assert.equal(result[1], rows[2]);
  assert.equal(JSON.stringify(rows), before);
  assert.notEqual(result, rows);
});

test('empty and whitespace-only queries return all records in input order', () => {
  const rows = [{id: 1, title: 'Alpha'}, {id: 2, title: ''}];
  assert.deepEqual(find(rows, ''), rows);
  assert.deepEqual(find(rows, ' \t\n '), rows);
  assert.deepEqual(find([], 'Alpha'), []);
});
